def gather(paths):
    files = []
    for p in paths:
        if p == "-":
            files.append("-")
            continue
        path = Path(p)
        if path.is_dir():
            files.extend(sorted(str(f) for f in path.rglob("*") if f.suffix.lower() in (".md", ".txt") and f.is_file()))
        elif path.is_file():
            files.append(str(path))
        else:
            raise FileNotFoundError(p)
    return files


